Encapsulation:
public class BankAccount {
    private String owner;  // private — hidden from outside
    private double balance;

    public BankAccount(String owner, double initial) {
        this.owner = owner;
        if (initial >= 0) this.balance = initial;
    }

    // Public getters — controlled access
    public String getOwner() { return owner; }
    public double getBalance() { return balance; }

    // Public methods — controlled mutation
    public void deposit(double amount) {
        if (amount > 0) balance += amount;
    }

    public boolean withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return true;
        }
        return false;
    }
}

BankAccount acc = new BankAccount("Alice", 1000);
acc.deposit(500);
acc.withdraw(200);
System.out.println(acc.getBalance()); // 1300.0

